assertionResults.fullName:
context compaction: bounded previews and preservation preserves protected tool instructions with class DefaultCompactor {
	nowFn;
	estimator;
	constructor(opts = {}) {
		this.nowFn = opts.now ?? Date.now;
		this.estimator = opts.tokenEstimator ?? __vite_ssr_import_1__.DEFAULT_TOKEN_ESTIMATOR;
	}
	compact(blocks, summary) {
		const preserved = [];
		let compactedCount = 0;
		for (const block of blocks) {
			if (isCompactable(block)) {
				compactedCount += 1;
			} else {
				preserved.push(block);
			}
		};
		if (compactedCount === 0) {
			// No compressible input: return the input untouched (no summary block).
			return blocks;
		};
		// Ordering: preserved blocks keep their original relative order; the single
		// summary block is appended after the last preserved block so the leading
		// system/user context (e.g. goal, security policy) is never displaced.
		preserved.push(makeSummaryBlock(summary, this.nowFn, this.estimator));
		return preserved;
	}
}

